"""Tests for tasks_api.repository (InMemoryTaskRepository, normalize_tags)."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2

    def test_add_and_get(self, repo):
        t = Task(id=1, title="Test")
        repo.add(t)
        assert repo.get(1) is t

    def test_get_missing_returns_none(self, repo):
        assert repo.get(99) is None

    def test_add_duplicate_raises(self, repo):
        t = Task(id=1, title="Test")
        repo.add(t)
        with pytest.raises(ValueError, match="already exists"):
            repo.add(t)

    def test_list_returns_all(self, repo):
        repo.add(Task(id=1, title="a"))
        repo.add(Task(id=2, title="b"))
        items = list(repo.list())
        assert len(items) == 2

    def test_update(self, repo):
        t = Task(id=1, title="orig")
        repo.add(t)
        t.title = "updated"
        repo.update(t)
        assert repo.get(1).title == "updated"

    def test_update_missing_raises(self, repo):
        t = Task(id=99, title="x")
        with pytest.raises(KeyError):
            repo.update(t)

    def test_delete_existing(self, repo):
        repo.add(Task(id=1, title="x"))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing(self, repo):
        assert repo.delete(99) is False


class TestNormalizeTags:
    def test_dedup_and_order(self):
        result = normalize_tags(["Work", "home", "  work  "])
        names = [t.name for t in result]
        assert names == ["work", "home"]

    def test_accepts_tag_objects(self):
        result = normalize_tags([Tag("alpha"), Tag("beta")])
        assert len(result) == 2

    def test_empty_list(self):
        assert normalize_tags([]) == []

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            normalize_tags(["valid", ""])
